//! Task-bound, explicitly selected, monotonic write leases.

use crate::{Phase, ReasonCode, TimePoint, Tool, validate_relative};
use chrono::{DateTime, Utc};
use serde::Serialize;
use std::time::Duration;

/// Server-assigned identity and client-requested lease bounds.
#[derive(Debug, Clone)]
pub struct GrantSpec {
    /// New unpredictable lease identifier generated by the server.
    pub grant_id: String,
    /// Task that owns this lease.
    pub task_id: String,
    /// Exact already-validated allowlist path.
    pub path: String,
    /// Lease lifetime in seconds, from 1 through 300.
    pub ttl_seconds: u16,
    /// Successful replacement limit, from 1 through 10.
    pub max_uses: u8,
}

/// A lease. The monotonic deadline is private and never serialized.
#[derive(Debug, Clone, Serialize)]
pub struct Grant {
    /// Lease identity; never accepted as an authentication credential.
    pub grant_id: String,
    /// Owning task identity.
    pub task_id: String,
    /// Only write_file leases are issued.
    pub tool: Tool,
    /// Exact relative file path.
    pub path: String,
    /// UTC display deadline; not used for authorization.
    pub expires_at: DateTime<Utc>,
    /// Remaining successful replacements.
    pub remaining_uses: u8,
    /// Whether the administrator revoked the lease.
    pub revoked: bool,
    #[serde(skip)]
    deadline: Duration,
}

/// Display status, with the same priority as task detail snapshots.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum GrantStatus {
    /// Any phase other than edit disables the lease.
    StageInactive,
    /// Administrator revocation takes precedence over expiry/exhaustion.
    Revoked,
    /// The monotonic clock reached or passed the deadline.
    Expired,
    /// No successful uses remain.
    UsedUp,
    /// A write may use the lease while inside the task execution boundary.
    Active,
}

impl Grant {
    /// Issue a write lease from validated bounds and a server clock sample.
    ///
    /// Returns INVALID_REQUEST for invalid TTL/use bounds or clock overflow,
    /// and PATH_DENIED for a noncanonical relative path. The caller additionally
    /// verifies edit phase, allowlist membership and absence of active conflicts.
    pub fn issue(spec: GrantSpec, now: TimePoint) -> Result<Self, ReasonCode> {
        if !(1..=300).contains(&spec.ttl_seconds) || !(1..=10).contains(&spec.max_uses) {
            return Err(ReasonCode::InvalidRequest);
        }
        validate_relative(&spec.path)?;
        let deadline = now
            .monotonic
            .checked_add(Duration::from_secs(u64::from(spec.ttl_seconds)))
            .ok_or(ReasonCode::InvalidRequest)?;
        let expires_at = now
            .utc
            .checked_add_signed(chrono::Duration::seconds(i64::from(spec.ttl_seconds)))
            .ok_or(ReasonCode::InvalidRequest)?;
        Ok(Self {
            grant_id: spec.grant_id,
            task_id: spec.task_id,
            tool: Tool::WriteFile,
            path: spec.path,
            expires_at,
            remaining_uses: spec.max_uses,
            revoked: false,
            deadline,
        })
    }

    /// Check expiry using monotonic time. Equality is expired.
    #[must_use]
    pub fn expired(&self, now: Duration) -> bool {
        now >= self.deadline
    }

    /// Produce an authoritative snapshot status from one task-locked sample.
    #[must_use]
    pub fn status(&self, phase: Phase, now: Duration) -> GrantStatus {
        if phase != Phase::Edit {
            GrantStatus::StageInactive
        } else if self.revoked {
            GrantStatus::Revoked
        } else if self.expired(now) {
            GrantStatus::Expired
        } else if self.remaining_uses == 0 {
            GrantStatus::UsedUp
        } else {
            GrantStatus::Active
        }
    }

    /// Consume one use after successful replacement, under the same task lock.
    ///
    /// Do not call for a rejection or a write that failed before replacement.
    /// Returns LEASE_USED_UP rather than panicking on accidental over-consumption.
    pub fn consume(&mut self) -> Result<(), ReasonCode> {
        self.remaining_uses = self
            .remaining_uses
            .checked_sub(1)
            .ok_or(ReasonCode::LeaseUsedUp)?;
        Ok(())
    }
}
